import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;
public class MinFlowersToCoverColors {
    private static final int INF = 1 << 29;
    public int[] solve(String[][] flowers, String[][] queries, int colorCount) {
        Map<String, Integer> colorId = new HashMap<>();
        int[] flowerMasks = new int[flowers.length];
        // 颜色种数小，压成二进制后并集就是按位或
        for (int i = 0;
        i < flowers.length;
        i++) {
            int mask = 0;
            for (String color : flowers[i]) {
                int id = colorId.computeIfAbsent(color, key -> colorId.size());
                mask |= 1 << id;
            }
            flowerMasks[i] = mask;
        }
        int size = 1 << colorCount;
        int[] dp = new int[size];
        Arrays.fill(dp, INF);
        dp[0] = 0;
        // 什么颜色都没有时不需要花
        // 由已凑出的 mask 再并上当前这朵花
        for (int flowerMask : flowerMasks) {
            for (int mask = 0;
            mask < size;
            mask++) {
                if (dp[mask] == INF) {
                    continue;
                }
                int nextMask = mask | flowerMask;
                dp[nextMask] = Math.min(dp[nextMask], dp[mask] + 1);
            }
        }
        // 查询要覆盖而不是恰好相等，把超集的最优朵数下推
        int[] best = dp.clone();
        for (int bit = 0;
        bit < colorCount;
        bit++) {
            for (int mask = 0;
            mask < size;
            mask++) {
                if ((mask & (1 << bit)) == 0) {
                    best[mask] = Math.min(best[mask], best[mask | (1 << bit)]);
                }
            }
        }
        int[] ans = new int[queries.length];
        for (int i = 0;
        i < queries.length;
        i++) {
            int queryMask = 0;
            boolean impossible = false;
            for (String color : queries[i]) {
                Integer id = colorId.get(color);
                if (id == null) {
                    impossible = true;
                    // 没有任何花包含该颜色
                    break;
                }
                queryMask |= 1 << id;
            }
            if (impossible || best[queryMask] >= INF) {
                ans[i] = -1;
            } else {
                ans[i] = best[queryMask];
            }
        }
        return ans;
    }
}

