// 输入前提：正整数面额，0≤amount≤10000。
// 代表题 LC 322：dp[j] 是凑出金额 j 的最少硬币数；dp[0]=0，凑不出保持 amount+1
// 容量正序，因为同一枚硬币可以重复用。换题：279 把 coins 换成 1²,2²,… 直到不超过 n；139 改成 boolean，枚举分割点且子串在字典里则 dp[j]|=dp[i]；方案数把 min 改成累加、不可达用 0、dp[0]=1
static int coinChange(int[] coins, int amount) {
    int inf = amount + 1;
    int[] dp = new int[amount + 1];
    java.util.Arrays.fill(dp, inf);
    dp[0] = 0;
    for (int coin : coins) {
        for (int j = coin;
        j <= amount;
        j++) {
            dp[j] = Math.min(dp[j], dp[j - coin] + 1);
        }
    }
    return dp[amount] > amount ? -1 : dp[amount];
}

