// 输入前提：正整数数组，n≤200、每项≤100。
// 代表题 LC 416：dp[j] 表示能否从不同下标的元素（数值可以重复）里凑出和 j；总和为奇直接失败，目标是 sum/2
// 容量必须倒序，dp[j-x] 仍是放入当前数之前的结果。换到 knapsack-01：dp 改成 long/int 价值，倒序不变，dp[j]=max(dp[j], dp[j-weight]+value)，答案取 dp[capacity]
static boolean canPartition(int[] nums) {
    int sum = 0;
    for (int x : nums) sum += x;
    if ((sum & 1) == 1) return false;
    int target = sum / 2;
    boolean[] dp = new boolean[target + 1];
    dp[0] = true;
    for (int x : nums) {
        for (int j = target;
        j >= x;
        j--) {
            if (dp[j - x]) dp[j] = true;
        }
    }
    return dp[target];
}

// 代表题 LC 1143：dp[i][j] 是 a 的前 i 个字符与 b 的前 j 个字符的最长公共子序列长度（可跳过，相对顺序不变）
// 第 0 行第 0 列表示空串，保持 0。换题：最长公共子串在字符不等时必须写成 0，相等才用左上+1，答案取整个表的最大值；编辑距离把第 0 行/列初始化成 i 和 j，不等时在插入、删除、替换里取 min 再 +1
static int longestCommonSubsequence(String a, String b) {
    int m = a.length();
    int n = b.length();
    int[][] dp = new int[m + 1][n + 1];
    for (int i = 1;
    i <= m;
    i++) {
        for (int j = 1;
        j <= n;
        j++) {
            if (a.charAt(i - 1) == b.charAt(j - 1)) {
                dp[i][j] = dp[i - 1][j - 1] + 1;
            } else {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }
    }
    return dp[m][n];
}

