// 保留模板导入，滚动变量不依赖集合
class Solution {
    public int climbStairs(int n) {
        // 只保留前两阶：twoBack 再往前一格，oneBack 上一格
        int twoBack = 0;
        int oneBack = 1;
        for (int i = 1;
        i <= n;
        i++) {
            int current = twoBack + oneBack;
            twoBack = oneBack;
            oneBack = current;
        }
        return oneBack;
    }
}

import java.util.*;
// 保留模板导入，滚动状态不依赖集合
class Solution {
    public int rob(int[] nums) {
        // twoBack：到上两间为止的最优；oneBack：到上一间为止的最优
        int twoBack = 0;
        int oneBack = 0;
        for (int money : nums) {
            // 不偷保留 oneBack，偷则只能接 twoBack 再加当前金额
            int current = Math.max(oneBack, twoBack + money);
            twoBack = oneBack;
            oneBack = current;
        }
        return oneBack;
    }
}

