// 滚动两个变量，导入保留
class Solution {
    public int maxProduct(int[] nums) {
        // 以当前位置结尾的最大、最小乘积
        int maxEnding = nums[0];
        int minEnding = nums[0];
        int answer = nums[0];
        for (int i = 1;
        i < nums.length;
        i++) {
            int num = nums[i];
            // 乘上负数会颠倒大小，先交换再更新
            if (num < 0) {
                int temp = maxEnding;
                maxEnding = minEnding;
                minEnding = temp;
            }
            // 从 num 重开，或接在上一段以当前位置结尾的乘积后
            maxEnding = Math.max(num, maxEnding * num);
            minEnding = Math.min(num, minEnding * num);
            answer = Math.max(answer, maxEnding);
        }
        return answer;
    }
}

