// Java 常用集合、队列、堆与数组工具
class Solution {
    public int longestValidParentheses(String s) {
        // 只存未匹配左括号下标；栈底 -1 表示“这段合法子串之前的非法位置”。
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(-1);
        // 没有真实左边界时，长度仍可从下标 0 算起。
        int best = 0;
        for (int i = 0;
        i < s.length();
        i++) {
            if (s.charAt(i) == '(') {
                stack.push(i);
            } else {
                stack.pop();
                // 当前 ')' 消耗一个待匹配的左括号或旧边界。
                if (stack.isEmpty()) {
                    // 弹空说明右括号多余，i 成为下一段的新非法边界。
                    stack.push(i);
                } else {
                    // 栈顶仍是本段左边最近的未匹配位置，差值即当前合法长度。
                    best = Math.max(best, i - stack.peek());
                }
            }
        }
        return best;
    }
}

