// 本解法用数组二分，导入保留
class Solution {
    public int lengthOfLIS(int[] nums) {
        // tails[i] 是长度为 i+1 的递增子序列的最小末尾
        int[] tails = new int[nums.length];
        int size = 0;
        for (int num : nums) {
            // 前 size 项严格递增，二分第一个 >= num 的位置
            int left = 0, right = size;
            while (left < right) {
                int middle = left + (right - left) / 2;
                if (tails[middle] < num) left = middle + 1;
                else right = middle;
            }
            // 换成更小末尾；下标落到 size 时长度增加
            tails[left] = num;
            if (left == size) size++;
        }
        return size;
    }
}

class Solution {
    public long maxSumIncreasingSubsequence(int[] nums) {
        if (nums.length == 0) return 0;
        long[] dp = new long[nums.length];
        long answer = Long.MIN_VALUE;
        for (int i = 0;
        i < nums.length;
        i++) {
            // 单元素也是严格递增子序列，和就是它自己。
            dp[i] = nums[i];
            for (int j = 0;
            j < i;
            j++) {
                if (nums[j] < nums[i]) {
                    dp[i] = Math.max(dp[i], dp[j] + nums[i]);
                }
            }
            answer = Math.max(answer, dp[i]);
        }
        return answer;
    }
}

