// 用 ArrayList 逐行保存三角形
class Solution {
    public List<List<Integer>> generate(int numRows) {
        List<List<Integer>> triangle = new ArrayList<>();
        for (int row = 0;
        row < numRows;
        row++) {
            List<Integer> current = new ArrayList<>();
            for (int col = 0;
            col <= row;
            col++) {
                if (col == 0 || col == row) {
                    // 每行首尾固定为 1
                    current.add(1);
                } else {
                    // 中间格等于上一行左上与正上方之和
                    int value = triangle.get(row - 1).get(col - 1)
                    + triangle.get(row - 1).get(col);
                    current.add(value);
                }
            }
            triangle.add(current);
        }
        return triangle;
    }
}

class Solution {
    public int findIntegers(int n) {
        int[] dp = new int[32];
        dp[0] = 1;
        dp[1] = 2;
        for (int i = 2;
        i < 32;
        i++) {
            // 末位 0：前 i-1 位任意合法；末位 1：前一位必须是 0
            dp[i] = dp[i - 1] + dp[i - 2];
        }
        int ans = 0, prevBit = 0;
        for (int i = 30;
        i >= 0;
        i--) {
            int bit = (n >> i) & 1;
            if (bit == 1) {
                ans += dp[i];
                // 这一位取 0，低 i 位任意不含连续 1 的数都比 n 小
                if (prevBit == 1) {
                    return ans;
                    // 已经出现连续 1，更小的后缀都不能再取
                }
                prevBit = 1;
            } else {
                prevBit = 0;
            }
        }
        return ans + 1;
        // n 本身也满足条件
    }
}

