// 只用数组做填表
class Solution {
    public int numSquares(int n) {
        // n+1 比任何合法个数都大，后面用更小值覆盖
        int[] dp = new int[n + 1];
        Arrays.fill(dp, n + 1);
        dp[0] = 0;
        for (int value = 1;
        value <= n;
        value++) {
            for (int x = 1;
            x * x <= value;
            x++) {
                int square = x * x;
                // 最后一块用 square，前面 value-square 已是最优
                dp[value] = Math.min(dp[value], dp[value - square] + 1);
            }
        }
        return dp[n];
    }
}

