// List 作为字典参数类型
class Solution {
    public boolean wordBreak(String s, List<String> wordDict) {
        boolean[] dp = new boolean[s.length() + 1];
        dp[0] = true;
        // 空前缀不需要任何单词
        for (int end = 1;
        end <= s.length();
        end++) {
            for (String word : wordDict) {
                int length = word.length();
                int start = end - length;
                // 前缀已能拆开，且这一段正好是当前单词
                if (start >= 0 && dp[start] && s.startsWith(word, start)) {
                    dp[end] = true;
                    break;
                }
            }
        }
        return dp[s.length()];
    }
}

