// 一维布尔数组表示能否凑出每个和
class Solution {
    public boolean canPartition(int[] nums) {
        int sum = 0;
        for (int num : nums) sum += num;
        // 奇数和无法拆成两个相等的整数和
        if ((sum & 1) == 1) return false;
        int target = sum / 2;
        boolean[] dp = new boolean[target + 1];
        dp[0] = true;
        for (int num : nums) {
            // 倒序读取更新前的状态，同一个 num 本轮只用一次
            for (int current = target;
            current >= num;
            current--) {
                dp[current] = dp[current] || dp[current - num];
            }
            if (dp[target]) return true;
        }
        return dp[target];
    }
}

class Solution {
    public long knapsack(int[] weights, int[] values, int capacity) {
        java.util.Objects.requireNonNull(weights);
        java.util.Objects.requireNonNull(values);
        if (weights.length != values.length || capacity < 0 || capacity == Integer.MAX_VALUE)
        throw new IllegalArgumentException();
        for (int w : weights) if (w < 0) throw new IllegalArgumentException();
        long[] dp = new long[capacity + 1];
        for (int i = 0;
        i < weights.length;
        i++) {
            int weight = weights[i];
            int value = values[i];
            // 从大到小写，dp[c-weight] 还是没选过第 i 件时的值。
            for (int c = capacity;
            c >= weight;
            c--) {
                dp[c] = Math.max(dp[c], dp[c - weight] + value);
            }
        }
        return dp[capacity];
    }
}

import java.util.*;
class Solution {
    public double maxKnowledge(int[] knowledge, int totalTime) {
        int n = knowledge.length;
        if (n == 0) return 0.0;
        // 每分钟最多 2 页，分钟数小于 ceil(n/2) 不可能读完。
        if (totalTime < (n + 1) / 2) return -1.0;
        int limit = Math.min(totalTime, n);
        long neg = Long.MIN_VALUE / 4;
        long[][] dp = new long[n + 1][limit + 1];
        for (long[] row : dp) Arrays.fill(row, neg);
        dp[0][0] = 0;
        for (int i = 1;
        i <= n;
        i++) {
            for (int t = 1;
            t <= limit;
            t++) {
                // 这一分钟只读第 i 页：完整收益在两倍尺度下是 2*knowledge。
                if (dp[i - 1][t - 1] != neg) {
                    dp[i][t] = Math.max(
                    dp[i][t],
                    dp[i - 1][t - 1] + 2L * knowledge[i - 1]
                    );
                }
                // 这一分钟读相邻两页，一半收益乘 2 后等于两页原始和。
                if (i >= 2 && dp[i - 2][t - 1] != neg) {
                    dp[i][t] = Math.max(
                    dp[i][t],
                    dp[i - 2][t - 1] + knowledge[i - 2] + knowledge[i - 1]
                    );
                }
            }
        }
        long best = neg;
        for (int t = 0;
        t <= limit;
        t++) {
            best = Math.max(best, dp[n][t]);
        }
        return best == neg ? -1.0 : best / 2.0;
    }
}

// LC62 原题：1<=m,n<=100，且最终答案<=2000000000；无障碍时各中间计数也不超过最终答案。
import java.util.*;
// Java 常用集合、队列、堆与数组工具
class Solution {
    public int uniquePaths(int m, int n) {
        // 滚动一行：dp[col] 是“当前行”到达该列的路径数。
        int[] dp = new int[n];
        Arrays.fill(dp, 1);
        // 第 0 行没有上方来路，只能一直向右。
        for (int row = 1;
        row < m;
        row++) {
            for (int col = 1;
            col < n;
            col++) {
                // 先加再写：旧 dp[col] 是上方，新 dp[col-1] 是左方。
                dp[col] = dp[col] + dp[col - 1];
            }
        }
        return dp[n - 1];
    }
}

// LC63 原题：非空 0/1 矩形，1<=m,n<=100，最终答案<=2000000000；不承诺所有中间格计数均无溢出。
import java.util.*;
class Solution {
    public int uniquePathsWithObstacles(int[][] obstacleGrid) {
        int rows = obstacleGrid.length;
        int cols = obstacleGrid[0].length;
        int[] dp = new int[cols];
        // 起点左侧放一条虚拟路径；起点是障碍时会在第一轮被清零
        dp[0] = 1;
        for (int row = 0;
        row < rows;
        row++) {
            for (int col = 0;
            col < cols;
            col++) {
                if (obstacleGrid[row][col] == 1) {
                    // 障碍不可经过，本列路径必须丢掉，不能留给下一行
                    dp[col] = 0;
                } else if (col > 0) {
                    // 旧 dp[col] 是上方，dp[col - 1] 是本行刚更新的左侧
                    dp[col] += dp[col - 1];
                }
            }
        }
        return dp[cols - 1];
    }
}

// LC64 原题：grid 非 null，为非空规则矩形，各行非 null 且等长，1≤行数、列数≤200，0≤grid[i][j]≤200。任意右/下路径至多399格，累计和≤79800，int 安全；主实现会修改输入。补充的 long、负权和空网格接口另有合同。
import java.util.*;
// Java 常用集合、队列、堆与数组工具
class Solution {
    public int minPathSum(int[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        // 原地覆盖：本格只依赖已更新的上、左，额外数组可以省掉。
        for (int r = 0;
        r < rows;
        r++) {
            for (int c = 0;
            c < cols;
            c++) {
                if (r == 0 && c == 0) continue;
                if (r == 0) {
                    // 第一行没有上方，只能接左边的最小和。
                    grid[r][c] += grid[r][c - 1];
                } else if (c == 0) {
                    // 第一列没有左方，只能接上边的最小和。
                    grid[r][c] += grid[r - 1][c];
                } else {
                    // 两条入边都合法时，取路径和更小的那条。
                    grid[r][c] += Math.min(grid[r - 1][c], grid[r][c - 1]);
                }
            }
        }
        return grid[rows - 1][cols - 1];
    }
}

class Solution {
    public int maximalSquare(char[][] matrix) {
        if (matrix.length == 0 || matrix[0].length == 0) return 0;
        int rows = matrix.length;
        int cols = matrix[0].length;
        int[] dp = new int[cols + 1];
        int maxSide = 0;
        for (int i = 1;
        i <= rows;
        i++) {
            int prev = 0;
            // 行首没有左上角，边长从 0 开始
            for (int j = 1;
            j <= cols;
            j++) {
                int temp = dp[j];
                // 覆盖前留下上方，循环末尾交给下一列当左上
                if (matrix[i - 1][j - 1] == '1') {
                    dp[j] = Math.min(Math.min(dp[j], dp[j - 1]), prev) + 1;
                    maxSide = Math.max(maxSide, dp[j]);
                } else {
                    dp[j] = 0;
                }
                prev = temp;
            }
        }
        return maxSide * maxSide;
    }
}

import java.util.*;
// 保留导入；解法只用字符串下标与 Math
class Solution {
    public String longestPalindrome(String s) {
        if (s.length() < 2) return s;
        // 不足两个字符时自身即最长回文
        int bestStart = 0;
        int bestLength = 1;
        for (int center = 0;
        center < s.length();
        center++) {
            // 奇数回文以单个字符为中心，左右从同一下标扩
            int len1 = expand(s, center, center);
            // 偶数回文以 center 与 center+1 之间的空隙为中心
            int len2 = expand(s, center, center + 1);
            int length = Math.max(len1, len2);
            if (length > bestLength) {
                bestLength = length;
                // 由中心回推起点，整数除法同时覆盖奇偶长度
                bestStart = center - (length - 1) / 2;
            }
        }
        return s.substring(bestStart, bestStart + bestLength);
    }
    private int expand(String s, int left, int right) {
        while (left >= 0 && right < s.length()
        && s.charAt(left) == s.charAt(right)) {
            left--;
            right++;
        }
        // 失配时指针已各多走一步，真实长度要减 1
        return right - left - 1;
    }
}

import java.util.*;
// Java 常用集合、队列、堆与数组工具
class Solution {
    public int longestCommonSubsequence(String text1, String text2) {
        // 较短串作为 text2，滚动数组只按它的长度开
        if (text1.length() < text2.length()) {
            return longestCommonSubsequence(text2, text1);
        }
        int[] dp = new int[text2.length() + 1];
        for (int i = 1;
        i <= text1.length();
        i++) {
            int diagonal = 0;
            // 本行开始时左上角是空前缀，长度为 0
            for (int j = 1;
            j <= text2.length();
            j++) {
                int top = dp[j];
                // 覆盖前留下上一行同列，稍后交给下一列当左上
                if (text1.charAt(i - 1) == text2.charAt(j - 1)) {
                    dp[j] = diagonal + 1;
                } else {
                    dp[j] = Math.max(dp[j], dp[j - 1]);
                }
                diagonal = top;
            }
        }
        return dp[text2.length()];
    }
}

import java.util.*;
// Java 常用集合、队列、堆与数组工具
class Solution {
    public int minDistance(String word1, String word2) {
        // dp[j]：当前 word1 前缀变成 word2 前 j 个字符的最少操作
        int[] dp = new int[word2.length() + 1];
        for (int j = 0;
        j <= word2.length();
        j++) dp[j] = j;
        for (int i = 1;
        i <= word1.length();
        i++) {
            int diagonal = dp[0];
            // 先拿走上一行的 dp[0]，作为本行第一列的左上
            dp[0] = i;
            // 变成空串只能连续删除 i 次
            for (int j = 1;
            j <= word2.length();
            j++) {
                int top = dp[j];
                if (word1.charAt(i - 1) == word2.charAt(j - 1)) {
                    dp[j] = diagonal;
                    // 末字符相同，沿用左上，不加操作
                } else {
                    int replace = diagonal;
                    int delete = top;
                    int insert = dp[j - 1];
                    dp[j] = Math.min(replace, Math.min(delete, insert)) + 1;
                }
                diagonal = top;
            }
        }
        return dp[word2.length()];
    }
}

class Solution {
    public int longestCommonSubstring(String s1, String s2) {
        if (s1.length() < s2.length()) {
            String temp = s1;
            s1 = s2;
            s2 = temp;
        }
        int[] dp = new int[s2.length() + 1];
        int best = 0;
        for (int i = 1;
        i <= s1.length();
        i++) {
            // 从右往左写，读到的 dp[j - 1] 仍是上一行
            for (int j = s2.length();
            j >= 1;
            j--) {
                if (s1.charAt(i - 1) == s2.charAt(j - 1)) {
                    dp[j] = dp[j - 1] + 1;
                    best = Math.max(best, dp[j]);
                } else {
                    dp[j] = 0;
                    // 字符不同则连续公共后缀中断
                }
            }
        }
        return best;
    }
}

import java.util.*;
import java.math.BigInteger;
public final class DecodeZero25 {
    // Canonical tokens 0..25: one digit always legal, two digits only 10..25.
    public static BigInteger count(String s){
        Objects.requireNonNull(s);
        for(int i=0;i<s.length();i++)if(s.charAt(i)<'0'||s.charAt(i)>'9')throw new IllegalArgumentException("digits");
        if(s.isEmpty())return BigInteger.ZERO;
        BigInteger before=BigInteger.ONE,current=BigInteger.ONE;
        for(int i=1;i<s.length();i++){
            int pair=(s.charAt(i-1)-'0')*10+s.charAt(i)-'0';
            BigInteger next=current;
            if(pair>=10&&pair<=25)next=next.add(before);
            before=current;
            current=next;
        }
        return current;
    }
}

import java.math.BigInteger;
import java.util.Arrays;
import java.util.Objects;
public final class DistinctSubsequences {
    private DistinctSubsequences() {
    }
    // UTF-16 code units; the LC115 English-letter contract is a subset.
    public static BigInteger count(String source, String target) {
        Objects.requireNonNull(source);
        Objects.requireNonNull(target);
        if (target.length() > source.length()) return BigInteger.ZERO;
        BigInteger[] dp = new BigInteger[target.length() + 1];
        Arrays.fill(dp, BigInteger.ZERO);
        dp[0] = BigInteger.ONE;
        for (int i = 0; i < source.length(); i++)
        for (int j = Math.min(target.length(), i + 1); j >= 1; j--)
        if (source.charAt(i) == target.charAt(j - 1)) dp[j] = dp[j].add(dp[j - 1]);
        return dp[target.length()];
    }
    // Independent oracle: enumerate index subsets, not DP transitions.
    private static String binary(int n, int bits) {
        StringBuilder s = new StringBuilder(n);
        for (int i = 0; i < n; i++) s.append((bits & (1 << i)) == 0 ? 'a' : 'b');
        return s.toString();
    }
}
